mapper.select:
select project_id, enabled, modules, update_by, update_time
from sys_project_mcp
where project_id = #{projectId}

mapper.update:
update sys_project_mcp
set enabled = #{enabled},
    modules = #{modules,typeHandler=com.cat2bug.system.mybatis.StringListJsonTypeHandler},
    update_by = #{updateBy},
    update_time = #{updateTime}
where project_id = #{projectId}
